CREATE TABLE tournament_device_assessment (
    device_id VARCHAR NOT NULL,
    assessment_date DATE NOT NULL,
    device_type VARCHAR NOT NULL,
    cgpi_score NUMERIC(10,4) NOT NULL,
    latency_ms NUMERIC(10,4),
    polling_rate_hz INTEGER,
    wireless_latency NUMERIC(10,4),
    qualifies_for_tournament BOOLEAN NOT NULL,
    standard_version VARCHAR DEFAULT 'v1.0'
) PARTITION BY LIST(device_type);

CREATE TABLE tournament_device_assessment_mice PARTITION OF tournament_device_assessment FOR VALUES IN ('Mouse');
CREATE TABLE tournament_device_assessment_keyboards PARTITION OF tournament_device_assessment FOR VALUES IN ('Keyboard');
CREATE TABLE tournament_device_assessment_controllers PARTITION OF tournament_device_assessment FOR VALUES IN ('Controller', 'Gamepad');

